function calendarParts(value){if(value instanceof Date&&!Number.isNaN(value.getTime()))return{y:value.getFullYear(),m:value.getMonth()+1,d:value.getDate()};const text=clean(value);if(!text)return null;const dateOnly=text.match(/^(\d{4})-(\d{2})-(\d{2})(?:$|T)/);if(dateOnly&&text.length===10)return{y:Number(dateOnly[1]),m:Number(dateOnly[2]),d:Number(dateOnly[3])};const date=new Date(text);if(Number.isNaN(date.getTime())){if(dateOnly)return{y:Number(dateOnly[1]),m:Number(dateOnly[2]),d:Number(dateOnly[3])};return null}return{y:date.getFullYear(),m:date.getMonth()+1,d:date.getDate()}}
