function monthKeysBetween(startValue,endValue){const startParts=calendarParts(startValue),endParts=calendarParts(endValue);if(!startParts||!endParts)return[];let y=startParts.y,m=startParts.m;const out=[];let guard=0;while((y<endParts.y||(y===endParts.y&&m<=endParts.m))&&guard<84){out.push(`${y}-${String(m).padStart(2,'0')}`);m+=1;if(m>12){m=1;y+=1}guard+=1}return out}
function profileDates(){let profile={};try{profile=typeof learnerProfile!=='undefined'&&learnerProfile?learnerProfile:readJson('eviaLearnerProfile',{})}catch{profile=readJson('eviaLearnerProfile',{})}return{start:clean(profile?.startDate),end:clean(profile?.endDate)}}
function timelineMonthRange(entries,learning){const dates=profileDates(),today=new Date();const all=[dates.start,dates.end,today,...entries.map(e=>evidenceDate(e)),...learning.map(e=>learningDate(e))].map(dateFor).filter(Boolean).sort((a,b)=>a-b);if(!all.length)return[monthKey(today)];const start=dates.start||all[0],end=dates.end||all[all.length-1];const keys=monthKeysBetween(start,end);return keys.length?keys:[monthKey(today)]}
function pathKey(path){try{return typeof evidencePathKey==='function'?evidencePathKey(path):JSON.stringify((Array.isArray(path)?path:[]).map(clean))}catch{return JSON.stringify((Array.isArray(path)?path:[]).map(clean))}}
function samePath(a,b){if(Array.isArray(a)&&Array.isArray(b))return a.length===b.length&&a.every((item,index)=>clean(item)===clean(b[index]));if(typeof a==='string'&&Array.isArray(b))return a===b.join(' > ')||a===b.join(' / ')||a===b.join(' › ');if(Array.isArray(a)&&typeof b==='string')return samePath(b,a);return clean(a)===clean(b)}
function mappings(){try{return typeof courseMetaMappings==='function'?courseMetaMappings():{}}catch{return{}}}
function codesForPath(path){const entryPath=Array.isArray(path)?path:[],result=[];for(const [code,mapped] of Object.entries(mappings()||{})){const candidates=Array.isArray(mapped)?mapped:[mapped],paths=candidates.some(candidate=>Array.isArray(candidate))?candidates:[mapped];if(paths.some(candidate=>samePath(candidate,entryPath)))result.push(code)}return[...new Set(result)].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'}))}
function completedSet(){try{if(typeof completedEvidencePaths!=='undefined'&&completedEvidencePaths instanceof Set)return new Set([...completedEvidencePaths])}catch{}const saved=readJson('eviaCompletedEvidencePathsV1',[]);return new Set(Array.isArray(saved)?saved:[])}
function completionDates(entries){const complete=completedSet(),map=new Map();(entries||[]).forEach(entry=>{const key=pathKey(entry?.path);if(!key||!complete.has(key))return;const date=dateFor(evidenceDate(entry));if(!date)return;const prev=map.get(key);if(!prev||date>prev)map.set(key,date)});if(!map.size&&!complete.size){(entries||[]).forEach(entry=>{const key=pathKey(entry?.path),date=dateFor(evidenceDate(entry));if(!key||!date)return;const prev=map.get(key);if(!prev||date>prev)map.set(key,date)})}return map}
function coverageAt(boundary,entries){const total=courseLeafCount();if(!total)return null;const dates=completionDates(entries);let count=0;dates.forEach(date=>{if(date<boundary)count+=1});return Math.min(100,(count/total)*100)}
function courseTimePercent(asOf){const dates=profileDates(),start=dateFor(dates.start),end=dateFor(dates.end);if(!start||!end||end<=start)return null;const when=asOf instanceof Date?asOf:new Date();return Math.max(0,Math.min(100,((when-start)/(end-start))*100))}
function epaPracticeAt(asOf){const state=readJson('eviaEpaPracticeV1',{}),percent=Number(state?.percent);if(!Number.isFinite(percent))return null;const done=dateFor(state?.completedAt);if(done&&asOf&&done>asOf)return null;return percent}
function fullLearnerName(){const p=getLearner();return clean([p?.firstName,p?.lastName].filter(Boolean).join(' '))||clean(p?.name)||clean(p?.displayName)||''}
function evidenceKind(entry){const type=clean(entry?.type).toLowerCase(),mime=clean(entry?.mimeType||entry?.blob?.type).toLowerCase();if(type==='observation'||/observation/.test(type))return'observation';if(type==='witness'||/witness/.test(type))return'witness';if(type.includes('photo')||mime.startsWith('image/'))return'photo';if(type.includes('video')||mime.startsWith('video/'))return'video';if(type.includes('audio')||mime.startsWith('audio/'))return'audio';if(type.includes('text')||type.includes('written')||mime.startsWith('text/'))return'written';if(type.includes('document')||mime.includes('pdf')||mime.includes('word')||mime.includes('sheet'))return'document';return type||'evidence'}
function evidenceTitle(entry){return clean(entry?.evidenceLabel)||clean(entry?.path?.at?.(-1))||clean(entry?.fileName)||'Evidence'}
function evidencePathLabel(entry){return Array.isArray(entry?.path)?entry.path.map(clean).filter(Boolean).join(' > '):''}
