function groupBy(items,keyFn){const map=new Map();items.forEach(item=>{const key=keyFn(item);if(!key)return;if(!map.has(key))map.set(key,[]);map.get(key).push(item)});return map}
function makeEvidenceEvents(entries){const groups=groupBy(entries,entry=>`${dayKey(evidenceDate(entry))}|${pathKey(entry?.path)}|${evidenceKind(entry)==='observation'?'milos':'learner'}`),out=[];groups.forEach(items=>{const first=items[0],kind=evidenceKind(first),assistant=kind==='observation'?'Milos':'',types=[...new Set(items.map(evidenceKind))].map(x=>x==='observation'?'assessor observation':x),codes=[...new Set(items.flatMap(item=>codesForPath(item?.path)))];out.push({id:`evidence:${dayKey(evidenceDate(first))}:${pathKey(first?.path)}:${assistant||'learner'}`,date:evidenceDate(first),kind:'evidence',assistant,title:assistant?`Milos - ${evidenceTitle(first)}`:evidenceTitle(first),summary:`${items.length} evidence item${items.length===1?'':'s'}${types.length?` - ${types.join(', ')}`:''}${codes.length?` - ${codes.length} mapped ${getCourseMeta()?.courseType==='nvq'?'AC':'KSB'}${codes.length===1?'':'s'}`:''}`,items})});return out}
function makeLearningEvents(learning){const out=[],college=learning.filter(isCollegeLearning),other=learning.filter(x=>!isCollegeLearning(x)),collegeGroups=groupBy(college,item=>monthKey(learningDate(item)));collegeGroups.forEach((items,key)=>{const dated=items.slice().sort((a,b)=>(dateFor(learningDate(a))||0)-(dateFor(learningDate(b))||0)),last=dated.at(-1)||items[0],labels=[...new Set(items.map(learningTitle).filter(Boolean))].slice(0,4),symi=items.some(isSymiLearning);out.push({id:`college:${key}`,date:learningDate(last),kind:'college',assistant:symi?'Symi':'',title:symi?'Symi - College learning':'College learning',summary:`${hoursTotal(items).toFixed(1)}h recorded${labels.length?` - ${labels.join(', ')}`:''}`,items})});const dayGroups=groupBy(other,item=>dayKey(learningDate(item)));dayGroups.forEach(items=>{const first=items[0],labels=[...new Set(items.map(learningTitle).filter(Boolean))].slice(0,3);out.push({id:`learning:${dayKey(learningDate(first))}`,date:learningDate(first),kind:'learning',assistant:'',title:labels[0]||'Learning recorded',summary:`${hoursTotal(items).toFixed(1)}h${labels.length>1?` - ${labels.slice(1).join(', ')}`:''}`,items})});return out}
function makeTinosEvents(learning){const state=readJson('eviaEmployerConfirmationsV1',{}),raw=[];Object.entries(state?.targets||{}).forEach(([id,item])=>{const date=clean(item?.confirmedAt);if(date)raw.push({date,label:`${id} workplace confirmation`,type:'target'})});learning.forEach(item=>{const date=clean(item?.employerConfirmedAt);if(date)raw.push({date,label:`${learningTitle(item)} learning confirmed`,type:'learning',hours:Number(item?.hours)||0})});const groups=groupBy(raw,item=>dayKey(item.date)),out=[];groups.forEach(items=>{const first=items[0],hours=items.reduce((s,x)=>s+(Number.isFinite(x.hours)?x.hours:0),0),targets=items.filter(x=>x.type==='target').length,logs=items.filter(x=>x.type==='learning').length,bits=[];if(targets)bits.push(`${targets} workplace area${targets===1?'':'s'}`);if(logs)bits.push(`${logs} learning confirmation${logs===1?'':'s'}${hours?` (${hours.toFixed(1)}h)`:''}`);out.push({id:`tinos:${dayKey(first.date)}`,date:first.date,kind:'assistant',assistant:'Tinos',title:'Tinos - Workplace confirmation',summary:bits.join(' - ')||'Employer contribution recorded',items})});return out}
function makeMilosReviewEvents(){const targets=readJson('eviaMilosTargetsV1',[]);if(!Array.isArray(targets))return[];const usable=targets.filter(item=>clean(item?.reviewDate)),groups=groupBy(usable,item=>dayKey(item.reviewDate)),out=[];groups.forEach(items=>{const first=items[0],labels=items.map(item=>clean(item?.title||item?.target)).filter(Boolean).slice(0,3);out.push({id:`milos-review:${dayKey(first.reviewDate)}`,date:first.reviewDate,kind:'assistant',assistant:'Milos',title:'Milos - Review',summary:`${items.length} target${items.length===1?'':'s'} set${labels.length?` - ${labels.join(', ')}`:''}`,items})});return out}
function makeEpaEvents(){const state=readJson('eviaEpaPracticeV1',{});if(!clean(state?.completedAt)||!Number.isFinite(Number(state?.percent)))return[];return[{id:`epa:${dayKey(state.completedAt)}`,date:state.completedAt,kind:'epa',assistant:'',title:'EPA practice completed',summary:`${Math.round(Number(state.percent))}% practice score`,items:[state]}]}
function buildTimelineEvents(entries,learning){const all=[...makeEvidenceEvents(entries),...makeLearningEvents(learning),...makeTinosEvents(learning),...makeMilosReviewEvents(),...makeEpaEvents()],seen=new Set();return all.filter(event=>{const key=`${event.id}|${dayKey(event.date)}`;if(!dayKey(event.date)||seen.has(key))return false;seen.add(key);return true}).sort((a,b)=>(dateFor(a.date)||0)-(dateFor(b.date)||0))}
function monthData(key,entries,learning,events){const evidence=entries.filter(item=>sameMonth(evidenceDate(item),key)),learn=learning.filter(item=>sameMonth(learningDate(item),key)),eventItems=events.filter(item=>sameMonth(item?.date,key));return{key,label:monthLabel(key),evidence,learning:learn,events:eventItems,hours:hoursTotal(learn),codes:[...new Set(evidence.flatMap(item=>codesForPath(item?.path)))]}}
function monthSnapshot(data,allEntries,allLearning){const start=monthStart(data.key),next=nextMonthStart(data.key),asOf=isCurrentMonth(data.key)?new Date():new Date(next.getTime()-1),attendance=currentAttendance(),startCoverage=coverageAt(start,allEntries),endCoverage=coverageAt(next,allEntries),completion=completionDates(allEntries);let newAreas=0;completion.forEach(date=>{if(date>=start&&date<next)newAreas+=1});const cumulativeLearner=allLearning.filter(item=>{const d=dateFor(learningDate(item));return d&&d<next}).reduce((sum,item)=>sum+(Number(item?.hours)||0),0),required=totalRequiredLearning(),time=courseTimePercent(asOf),expected=required!==null&&time!==null?required*(time/100):null,assistants=[...new Set(data.events.map(e=>e.assistant).filter(Boolean))];return{month:data.key,label:data.label,status:isPastMonth(data.key)?'Complete':isCurrentMonth(data.key)?'Live':'Upcoming',timePercent:time,startCoverage,endCoverage,currentCourseProgress:currentCourseProgress(),newAreas,evidenceItems:data.evidence.length,learningEntries:data.learning.length,learningHours:data.hours,criteria:data.codes.length,cumulativeLearnerHours:cumulativeLearner,requiredLearning:required,expectedLearning:expected,collegeLearningHours:Number(attendance?.collegeLearningHours)||0,collegeAttendance:Number.isFinite(Number(attendance?.college))?Number(attendance.college):null,workplaceAttendance:Number.isFinite(Number(attendance?.workplace))?Number(attendance.workplace):null,combinedAttendance:combinedAttendanceValue(attendance),epaPractice:epaPracticeAt(asOf),assistants,assistantEvents:data.events.filter(e=>e.assistant).length,generatedAt:new Date().toISOString()}}
function saveManifest(data,snapshot){const archive=readJson(MONTH_ARCHIVE_KEY,{});archive[data.key]={month:data.key,updatedAt:new Date().toISOString(),status:snapshot.status,evidenceIds:data.evidence.map(x=>String(x?.id||'')).filter(Boolean),learningIds:data.learning.map(x=>String(x?.id||'')).filter(Boolean),snapshot};writeJson(MONTH_ARCHIVE_KEY,archive)}
function assistantClass(name){const value=clean(name).toLowerCase();if(value==='milos')return'milos';if(value==='symi')return'symi';if(value==='tinos')return'tinos';return''}
function eventDetailMarkup(event){const items=Array.isArray(event.items)?event.items:[];if(event.kind==='evidence'){const first=items[0],codes=[...new Set(items.flatMap(x=>codesForPath(x?.path)))];return`<p>${esc(evidencePathLabel(first))}</p>${codes.length?`<p><strong>Mapped:</strong> ${esc(codes.join(', '))}</p>`:''}${first?.assessmentGuide?`<p><strong>Evidence guide:</strong><br>${esc(first.assessmentGuide).replaceAll('\n','<br>')}</p>`:''}`}if(event.kind==='learning'||event.kind==='college')return items.slice(0,6).map(item=>`<p><strong>${esc(learningTitle(item))}</strong>${Number(item?.hours)>0?` - ${Number(item.hours).toFixed(1)}h`:''}<br>${esc(item?.text||'')}</p>`).join('');return`<p>${esc(event.summary)}</p>`}
