function pdfSafe(value){return String(value??'').replace(/[–—]/g,'-').replace(/→/g,'->').replace(/•/g,'-').replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/…/g,'...').replace(/›/g,'>').replace(/≤/g,'<=').replace(/≥/g,'>=').replace(/[^\x09\x0A\x0D\x20-\x7E£€]/g,'')}
function pdfColor(rgb){const {rgb:make}=window.PDFLib;return make(rgb[0]/255,rgb[1]/255,rgb[2]/255)}
function wrapPdf(font,text,size,maxWidth){const result=[];for(const paragraph of pdfSafe(text).split(/\n/)){if(!paragraph){result.push('');continue}const words=paragraph.split(/\s+/);let line='';for(const word of words){const candidate=line?`${line} ${word}`:word;if(font.widthOfTextAtSize(candidate,size)<=maxWidth){line=candidate;continue}if(line)result.push(line);line='';if(font.widthOfTextAtSize(word,size)<=maxWidth){line=word;continue}let chunk='';for(const ch of word){const next=chunk+ch;if(font.widthOfTextAtSize(next,size)>maxWidth&&chunk){result.push(chunk);chunk=ch}else chunk=next}line=chunk}if(line)result.push(line)}return result}
function drawTextLines(page,font,lines,x,y,size,lineHeight,color,maxLines=Infinity){const list=lines.slice(0,maxLines);list.forEach((line,index)=>page.drawText(line,{x,y:y-(index*lineHeight),size,font,color}));return y-(list.length*lineHeight)}
function fitImageDims(width,height,maxW,maxH){if(!width||!height)return{w:maxW,h:maxH};const scale=Math.min(maxW/width,maxH/height);return{w:width*scale,h:height*scale}}
function waitEvent(target,event,timeout=5000){return new Promise((resolve,reject)=>{let timer=setTimeout(()=>{cleanup();reject(new Error(`${event} timeout`))},timeout);const done=()=>{cleanup();resolve()},fail=()=>{cleanup();reject(new Error(`${event} failed`))};function cleanup(){clearTimeout(timer);target.removeEventListener(event,done);target.removeEventListener('error',fail)}target.addEventListener(event,done,{once:true});target.addEventListener('error',fail,{once:true})})}
async function canvasJpegBytes(draw,width=360,height=240){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#f4f4f2';ctx.fillRect(0,0,width,height);await draw(ctx,canvas);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.82));return blob?new Uint8Array(await blob.arrayBuffer()):null}
