async function videoThumbnailBytes(blob){if(!(blob instanceof Blob)||!blob.size)return null;const url=URL.createObjectURL(blob),video=document.createElement('video');video.muted=true;video.playsInline=true;video.preload='metadata';video.src=url;try{await waitEvent(video,'loadeddata',7000);if(Number.isFinite(video.duration)&&video.duration>.4){video.currentTime=Math.min(.6,Math.max(.1,video.duration*.08));try{await waitEvent(video,'seeked',3500)}catch{}}return await canvasJpegBytes(async(ctx,canvas)=>{const vw=video.videoWidth||canvas.width,vh=video.videoHeight||canvas.height,scale=Math.max(canvas.width/vw,canvas.height/vh),w=vw*scale,h=vh*scale;ctx.drawImage(video,(canvas.width-w)/2,(canvas.height-h)/2,w,h)})}catch{return null}finally{video.removeAttribute('src');video.load?.();URL.revokeObjectURL(url)}}
async function thumbnailBytes(entry){const kind=evidenceKind(entry);try{if(kind==='photo')return await imageThumbnailBytes(entry?.blob);if(kind==='video'||(kind==='witness'&&clean(entry?.mimeType).startsWith('video/')))return await videoThumbnailBytes(entry?.blob)}catch{}return null}
function drawPlaceholder(page,x,y,w,h,label,fonts){const line=pdfColor([215,215,210]),fill=pdfColor([248,248,245]),muted=pdfColor([110,110,105]);page.drawRectangle({x,y:y-h,width:w,height:h,borderColor:line,borderWidth:1,color:fill});const text=pdfSafe(label).toUpperCase().slice(0,18),tw=fonts.bold.widthOfTextAtSize(text,10);page.drawText(text,{x:x+(w-tw)/2,y:y-(h/2)-4,size:10,font:fonts.bold,color:muted})}
