function drawMetric(page,fonts,x,y,w,label,value){const line=pdfColor([225,225,220]),fill=pdfColor([249,249,247]),dark=pdfColor([45,45,45]),muted=pdfColor([105,105,100]);page.drawRectangle({x,y:y-48,width:w,height:48,borderColor:line,borderWidth:.8,color:fill});page.drawText(pdfSafe(value),{x:x+10,y:y-20,size:14,font:fonts.bold,color:dark});page.drawText(pdfSafe(label),{x:x+10,y:y-36,size:8.5,font:fonts.regular,color:muted})}
