async function ensurePdfLib(){if(window.PDFLib?.PDFDocument)return window.PDFLib;const existing=document.getElementById(PDF_SCRIPT_ID);if(existing){if(existing.dataset.loaded==='1'&&window.PDFLib?.PDFDocument)return window.PDFLib;await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(new Error('PDF library did not load.')),12000);existing.addEventListener('load',()=>{clearTimeout(timeout);resolve()},{once:true});existing.addEventListener('error',()=>{clearTimeout(timeout);reject(new Error('PDF library could not be loaded.'))},{once:true})});if(window.PDFLib?.PDFDocument)return window.PDFLib}const script=document.createElement('script');script.id=PDF_SCRIPT_ID;script.src=PDF_LIBRARY_URL;script.async=true;await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(new Error('PDF library did not load.')),12000);script.addEventListener('load',()=>{clearTimeout(timeout);script.dataset.loaded='1';resolve()},{once:true});script.addEventListener('error',()=>{clearTimeout(timeout);reject(new Error('PDF library could not be loaded.'))},{once:true});document.head.appendChild(script)});if(!window.PDFLib?.PDFDocument)throw new Error('PDF library is unavailable.');return window.PDFLib}
